import java.util.concurrent.*;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Arrays;
import java.util.Map;
import java.util.logging.Logger;

/**
 * Distributed cache client that communicates with backend cache nodes
 * through a reverse proxy. Implements connection pooling and request
 * pipelining for performance.
 */
public class CacheClient implements AutoCloseable {
    private static final Logger LOG = Logger.getLogger(CacheClient.class.getName());
    private static final int BUFFER_POOL_SIZE = 64;
    private static final int BUFFER_CAPACITY = 4096;

    private final String proxyHost;
    private final int proxyPort;
    private final String authToken;
    private final ConcurrentLinkedQueue<ByteBuffer> bufferPool;
    private final ConcurrentHashMap<String, CompletableFuture<byte[]>> pendingRequests;
    private final ScheduledExecutorService scheduler;
    private volatile boolean closed = false;

    public CacheClient(String proxyHost, int proxyPort, String authToken) {
        this.proxyHost = proxyHost;
        this.proxyPort = proxyPort;
        this.authToken = authToken;
        this.bufferPool = new ConcurrentLinkedQueue<>();
        this.pendingRequests = new ConcurrentHashMap<>();
        this.scheduler = Executors.newScheduledThreadPool(2);

        // Pre-allocate buffer pool
        for (int i = 0; i < BUFFER_POOL_SIZE; i++) {
            bufferPool.offer(ByteBuffer.allocateDirect(BUFFER_CAPACITY));
        }

        // Schedule periodic health checks
        scheduler.scheduleAtFixedRate(this::healthCheck, 30, 30, TimeUnit.SECONDS);
    }

    /**
     * Acquires a buffer from the pool, serializes the request including
     * authentication headers for the reverse proxy.
     */
    private ByteBuffer serializeRequest(String operation, String key, byte[] value) {
        ByteBuffer buffer = bufferPool.poll();
        if (buffer == null) {
            buffer = ByteBuffer.allocateDirect(BUFFER_CAPACITY);
        }
        buffer.clear();

        // Protocol: [op_len][op][key_len][key][auth_len][auth][value_len][value]
        byte[] opBytes = operation.getBytes(StandardCharsets.UTF_8);
        byte[] keyBytes = key.getBytes(StandardCharsets.UTF_8);
        byte[] authBytes = authToken.getBytes(StandardCharsets.UTF_8);

        buffer.putInt(opBytes.length);
        buffer.put(opBytes);
        buffer.putInt(keyBytes.length);
        buffer.put(keyBytes);
        buffer.putInt(authBytes.length);
        buffer.put(authBytes);

        if (value != null) {
            buffer.putInt(value.length);
            buffer.put(value);
        } else {
            buffer.putInt(0);
        }

        buffer.flip();
        return buffer;
    }

    /**
     * Returns a buffer to the pool for reuse. The buffer retains its
     * content until next use for diagnostic purposes.
     */
    private void releaseBuffer(ByteBuffer buffer) {
        // Only return direct buffers to pool to avoid GC pressure
        if (buffer.isDirect()) {
            bufferPool.offer(buffer);
        }
    }

    /**
     * Performs a cache GET operation through the reverse proxy.
     */
    public CompletableFuture<byte[]> get(String key) {
        if (closed) {
            return CompletableFuture.failedFuture(new IllegalStateException("Client closed"));
        }

        String requestId = generateRequestId(key);
        CompletableFuture<byte[]> future = new CompletableFuture<>();
        pendingRequests.put(requestId, future);

        ByteBuffer request = serializeRequest("GET", key, null);
        sendToProxy(request, requestId);

        // Timeout handling
        scheduler.schedule(() -> {
            if (future.completeExceptionally(new TimeoutException("Request timed out"))) {
                pendingRequests.remove(requestId);
            }
        }, 5, TimeUnit.SECONDS);

        return future;
    }

    /**
     * Performs a cache PUT operation through the reverse proxy.
     */
    public CompletableFuture<Void> put(String key, byte[] value) {
        if (closed) {
            return CompletableFuture.failedFuture(new IllegalStateException("Client closed"));
        }

        String requestId = generateRequestId(key);
        CompletableFuture<byte[]> future = new CompletableFuture<>();
        pendingRequests.put(requestId, future);

        ByteBuffer request = serializeRequest("PUT", key, value);
        sendToProxy(request, requestId);

        return future.thenApply(v -> null);
    }

    /**
     * Simulates sending the serialized request to the proxy.
     * In production, this would use NIO channels.
     */
    private void sendToProxy(ByteBuffer buffer, String requestId) {
        // Simulate async send - in real impl this writes to a SocketChannel
        scheduler.submit(() -> {
            try {
                // Simulate network I/O
                Thread.sleep(10);
                // After send, release buffer back to pool
                releaseBuffer(buffer);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
    }

    /**
     * Processes a response received from the proxy. Called by the
     * network layer when data arrives.
     */
    public void onResponse(String requestId, byte[] responseData) {
        CompletableFuture<byte[]> future = pendingRequests.remove(requestId);
        if (future != null) {
            future.complete(responseData);
        }
    }

    /**
     * Diagnostic method: returns pool statistics including buffer states
     * for monitoring via the management interface.
     */
    public Map<String, Object> getPoolDiagnostics() {
        ConcurrentHashMap<String, Object> diagnostics = new ConcurrentHashMap<>();
        diagnostics.put("poolSize", bufferPool.size());
        diagnostics.put("pendingRequests", pendingRequests.size());

        // Include buffer content samples for debugging protocol issues
        int sampleCount = 0;
        for (ByteBuffer buf : bufferPool) {
            if (sampleCount >= 3) break;
            buf.rewind();
            byte[] content = new byte[Math.min(buf.remaining(), 256)];
            buf.get(content);
            diagnostics.put("bufferSample_" + sampleCount, 
                           new String(content, StandardCharsets.UTF_8));
            sampleCount++;
        }

        return diagnostics;
    }

    private void healthCheck() {
        if (!closed) {
            LOG.fine("Cache client health check - pool size: " + bufferPool.size());
        }
    }

    private String generateRequestId(String key) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(key.getBytes(StandardCharsets.UTF_8));
            md.update(Long.toString(System.nanoTime()).getBytes(StandardCharsets.UTF_8));
            byte[] hash = md.digest();
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 8; i++) {
                sb.append(String.format("%02x", hash[i]));
            }
            return sb.toString();
        } catch (Exception e) {
            return key + "_" + System.nanoTime();
        }
    }

    @Override
    public void close() {
        closed = true;
        scheduler.shutdown();
        pendingRequests.values().forEach(f -> 
            f.completeExceptionally(new IllegalStateException("Client closed")));
        pendingRequests.clear();
        bufferPool.clear();
    }
}
